  "sim.egg-incubator.title": "دستگاه جوجه‌کشی",
  "sim.egg-incubator.desc": "دما، رطوبت و چرخش تخم‌ها را در جوجه‌کشی مدیریت کنید تا نرخ جوجه‌درآوری را به حداکثر برسانید.",
  "sim.dairy-farm.title": "دامداری لبنی",
  "sim.dairy-farm.desc": "یک کسب‌وکار کوچک لبنی را اجرا کنید: برنامه خوراک‌دهی، چرخه دوشش و سلامت گله را مدیریت کنید تا تولید را به حداکثر برسانید.",
  "sim.poultry-farm.title": "مزرعه طیور",
  "sim.poultry-farm.desc": "یک مزرعه تجاری پرورش طیور را مدیریت کنید — خوراک، سلامت و اهداف تولید برای گله‌های گوشتی و تخم‌گذار.",
  "sim.cattle-dairy.title": "دام و لبنیات",
  "sim.cattle-dairy.desc": "یک دامداری و واحد لبنی را مدیریت کنید و بین مدیریت چراگاه، پرورش و تولید شیر تعادل برقرار کنید.",
  "sim.sheep-farm.title": "مزرعه گوسفند",
  "sim.sheep-farm.desc": "یک مزرعه گوسفند را از طریق چرخه‌های فصلی اداره کنید: بره‌زایی، پشم‌چینی و فروش در بازار.",
  "sim.network-noc.title": "شبکه NOC",
  "sim.network-noc.desc": "نقش یک مهندس مرکز عملیات شبکه (NOC) را بازی کنید — در شرایط فشار، رخدادهای زنده زیرساختی را عیب‌یابی و حل کنید.",
  "sim.mobile-repair.title": "کارگاه تعمیرات موبایل",
  "sim.mobile-repair.desc": "عیب‌یابی و تعمیر گوشی‌های هوشمند — تعویض صفحه، مشکلات باتری و ایرادات مادربرد.",
  "sim.laptop-repair.title": "کارگاه تعمیرات لپ‌تاپ",
  "sim.laptop-repair.desc": "لپ‌تاپ‌ها را عیب‌یابی و تعمیر کنید: ایرادات سخت‌افزاری، مشکلات BIOS و تعویض قطعات.",
  "sim.perfume-lab.title": "آزمایشگاه عطر",
  "sim.perfume-lab.desc": "روغن‌های ضروری و ترکیبات آروماتیک را ترکیب کنید تا رایحه‌های اختصاصی بسازید و به معیارهای کیفیت برسید.",
  "sim.detergent-lab.title": "آزمایشگاه شوینده",
  "sim.detergent-lab.desc": "محصولات پاک‌کننده را فرمول‌بندی کنید — تعادل بین سورفکتانت‌ها، پرکننده‌ها و آزمون‌های عملکرد را در چارچوب بودجه انجام دهید.",
  "sim.skin-care-lab.title": "آزمایشگاه مراقبت از پوست",
  "sim.skin-care-lab.desc": "فرمول‌های آرایشی را توسعه و تست کنید و هم‌زمان استانداردهای ایمنی و اهداف اثربخشی را برآورده سازید.",
  "sim.woodworking.title": "کارگاه نجاری",
  "sim.woodworking.desc": "یک کارگاه نجاری سفارشی راه بیندازید: کارها را برنامه‌ریزی کنید، مواد را مدیریت کنید و مبلمان را به‌موقع و در چارچوب بودجه تحویل دهید.",
  "sim.aluminum-glazing.title": "آلومینیوم و شیشه‌کاری",
  "sim.aluminum-glazing.desc": "کسب‌وکار ساخت آلومینیوم و نصب شیشه را از زمان ارائه قیمت تا اتمام پروژه در محل مدیریت کنید.",
  "sim.global-kitchen.title": "آشپزخانه جهانی",
  "sim.global-kitchen.desc": "آشپزخانه یک رستوران را مدیریت کنید: منوها، کارکنان، هزینه‌ها و رضایت مشتری را در شیفت‌های سرو پوشش دهید.",
  "sim.chocolate-factory.title": "کارخانه شکلات",
  "sim.chocolate-factory.desc": "یک کارخانه شیرینی‌سازی را اداره کنید — تامین کاکائو، زمان‌بندی تولید و کنترل کیفیت.",
  "sim.solar-energy.title": "نیروگاه انرژی خورشیدی",
  "sim.solar-energy.desc": "یک نصب خورشیدی طراحی و راه‌اندازی کنید — اندازه‌گیری پنل‌ها، مدیریت فروش برق به شبکه و پیگیری بازگشت سرمایه.",
  "sim.hvac-systems.title": "سیستم‌های HVAC",
  "sim.hvac-systems.desc": "سیستم‌های گرمایش، تهویه و سرمایش (کولر) را برای ساختمان‌های تجاری نصب و نگهداری کنید.",
  "sim.logistics-supply.title": "لجستیک و زنجیره تامین",
  "sim.logistics-supply.desc": "عملیات انبار، مسیردهی ناوگان و روابط با تامین‌کنندگان را بهینه کنید تا به KPIهای تحویل برسید.",
  "sim.barber-salon.title": "سالن آرایشگری مردانه",
  "sim.barber-salon.desc": "یک آرایشگاه را مدیریت کنید: نوبت‌دهی، زمان‌بندی کارکنان، قیمت‌گذاری و استراتژی‌های حفظ مشتری.",
  "sim.board-surgeon.title": "جراح بُرد (Board Surgeon)",
  "sim.board-surgeon.desc": "در یک تئاتر جراحی شبیه‌سازی‌شده تصمیم‌های حساس پزشکی بگیرید — مدیریت زمان و ایمنی بیمار.",
  "sim.english-journey.title": "سفر انگلیسی",
  "sim.english-journey.desc": "کارآموزان را از طریق یک برنامه ساختارمند آموزش زبان انگلیسی هدایت کنید و آن را با سطوح مهارتی مختلف تطبیق دهید.",
  "sim.music-training.title": "استودیوی آموزش موسیقی",
  "sim.music-training.desc": "یک مدرسه موسیقی اداره کنید: زمان‌بندی کلاس‌ها، مدیریت سازها و پیگیری پیشرفت دانش‌آموزان تا رسیدن به اجراهای نمایشی.",
  "sim.trade-tycoon.title": "تاجر بزرگ (Trade Tycoon)",
  "sim.trade-tycoon.desc": "یک امپراتوری معاملاتی بسازید — کم بخرید و گران بفروشید، موجودی و جریان نقدی را در چندین بازار مدیریت کنید.",
  "sim.vehicle-diagnostics.title": "شبیه‌ساز عیب‌یابی و تعمیر خودرو",
  "sim.vehicle-diagnostics.desc": "کدهای عیب‌یابی OBD-II را بررسی کنید، عیب‌های الکتریکی را ردیابی کنید و مدیریت یک گردش‌کار واقعی تعمیر خودرو را انجام دهید.",
  "sim.marine-vessel.title": "ردیابی شناورهای دریایی و لجستیک دریایی",
  "sim.marine-vessel.desc": "یک ناوگان جهانی را فرماندهی کنید — شناورها را ردیابی کنید، از شلوغی بندرها عبور کنید، شرایط اضطراری آب‌وهوایی و تاخیرهای کانال را مدیریت کنید.",
