  "starchef.howTo.3": "مواد اشتباه −10 امتیاز هزینه دارد",
  "starchef.howTo.4": "اگر اشتباه کردی، «پاک‌سازی بشقاب» همه مواد را حذف می‌کند",
  "starchef.howTo.5": "قبل از تمام شدن زمان، تا جایی که می‌توانی سفارش‌های درست را سرو کن",
  "akinator.q.arab": "این شخصیت اهل دنیای عربی است یا اسلامی؟",
  "akinator.q.sports": "این شخص یک ورزشکار مشهور است؟",
  "akinator.q.scientist": "این شخص دانشمند است یا مخترع؟",
  "akinator.char.ibneKhaldun": "ابن خلدون",
  "akinator.char.saladin": "صلاح‌الدین",
  "akinator.char.rumi": "مولوی",
  "akinator.char.avicenna": "ابن‌سینا",
  "akinator.char.muhammadAli": "محمد علی",
  "akinator.char.ronaldo": "کریستیانو رونالدو",
  "akinator.char.messi": "لیونل مسی",
  "akinator.howTo.1": "هر شخصیت واقعی یا خیالی را در نظر بگیر",
  "akinator.howTo.2": "به سوال‌ها صادقانه پاسخ بده (بله/احتمالاً/نمی‌دانم/احتمالاً نه/نه)",
  "akinator.howTo.3": "هوش مصنوعی با هر پاسخ، گزینه‌ها را محدودتر می‌کند",
  "akinator.howTo.4": "ببین آکیناتور می‌تواند شخصیت تو را با 20 سوال حدس بزند!",
  "neonbreach.howTo.1": "دنبال کردن ترتیب گره‌های روشن را با دقت ببین",
  "neonbreach.howTo.2": "بعد همان ترتیب دقیق را با ضربه زدن تکرار کن",
  "neonbreach.howTo.3": "هر سطح درست، یک گره دیگر را برای به خاطر سپردن اضافه می‌کند",
  "neonbreach.howTo.4": "یک ضربه اشتباه و دیوار آتش تو را می‌گیرد!",
  "earmaster.howTo.1": "با دقت به نت موسیقی که پخش می‌شود گوش بده",
  "earmaster.howTo.2": "از بین ۷ گزینه، بگو کدام نت را شنیدی",
  "earmaster.howTo.3": "از دکمه پخش برای یک بار دوباره پخش کردن نت استفاده کن",
  "earmaster.howTo.4": "برای دیدن امتیاز نهایی، 10 دور را کامل کن",
  "uno.howTo.1": "با رنگ یا عدد، کارت بالایی دسته را مطابق کن",
  "uno.howTo.2": "برای بازی کردن، روی یک کارت از دستت ضربه بزن",
  "uno.howTo.3": "اگر هیچ تطابقی نداری، برای اضافه کردن یک کارت روی Draw ضربه بزن",
  "uno.howTo.4": "اول کسی که دستش را خالی کند برنده است!",
  "briscola.howTo.1": "بریسکولا یک بازی ورق ایتالیاییِ ترفندگیری است",
  "briscola.howTo.2": "رنگ اترامپ (بریسکولا) از همه رنگ‌های دیگر قوی‌تر است",
  "briscola.howTo.3": "ترفند بگیرید تا امتیاز جمع کنید — آس=11، 3=10، شاه=4، ملکه=3، سرباز=2",
  "briscola.howTo.4": "بالاترین امتیاز بعد از تمام شدن بازی برنده است",
  "card99.howTo.1": "کارت بازی کنید تا مجموعِ در حال اجرا در 99 یا کمتر بماند",
  "card99.howTo.2": "کارت‌های ویژه: شاه=0، ملکه=نگه‌دار، سرباز=−10، آس=1 یا 11",
  "card99.howTo.3": "اگر مجموع را از 99 بالاتر ببرید، یک جان را از دست می‌دهید",
  "card99.howTo.4": "آخرین نفری که با جان باقی می‌ماند برنده است!",
  "dominoes.howTo.1": "عددهای دو سر زنجیره دومینو را با هم جور کنید",
  "dominoes.howTo.2": "کاشی‌هایی از دستتان بازی کنید که با یک سرِ باز هم‌خوانی دارند",
  "dominoes.howTo.3": "اگر نتوانستید بازی کنید، از دسته بکشید",
  "dominoes.howTo.4": "اول کسی که دستش را خالی کند (یا کمترین مجموعِ پیمانه) برنده است!",
  "farkle.howTo.1": "6 تاس را بیندازید و هر تاسِ امتیازآور را کنار بگذارید",
  "farkle.howTo.2": "1ها = 100 امتیاز · 5ها = 50 امتیاز · سه‌تایی = عددِ روی صورت × 100",
  "farkle.howTo.3": "اگر در هیچ‌یک از تاس‌ها در یک پرتاب امتیاز نیفتاد، این یعنی FARKLE — نوبتتان را از دست می‌دهید!",
  "farkle.howTo.4": "امتیازها را جمع کنید تا نگه‌شان دارید، یا دوباره بیندازید برای ریسک/پاداش بیشتر",
  "quiz.howTo.1": "تا می‌توانید سریع به 20 سوال چندگزینه‌ای جواب بدهید",
  "quiz.howTo.2": "برای هر سوال 3 ثانیه وقت دارید — سریع جواب بدهید!",
  "quiz.howTo.3": "پاسخ‌های صحیحِ سریع‌تر، امتیاز پاداش بیشتری دارند",
  "quiz.howTo.4": "برای دیدن رتبه نهایی، به همه سوال‌ها پاسخ بدهید",
  "memory.howTo.1": "همزمان دو کارت را برگردانید تا جفت‌های هم‌خوان را پیدا کنید",
  "memory.howTo.2": "اگر هم‌خوان باشند، همان‌طور رو به بالا می‌مانند",
  "memory.howTo.3": "اگر نه، هر دو برمی‌گردند رو به پایین — یادتان باشد کجا بودند!",
  "memory.howTo.4": "همه جفت‌ها را با کمترین حرکت ممکن پیدا کنید تا امتیاز بالایی بگیرید",
  "word.howTo.1": "حروفِ به‌هم‌ریخته را مرتب کنید تا کلمه پنهان را بسازید",
  "word.howTo.2": "برای ساخت جواب، حروف را به ترتیب درست لمس کنید",
  "word.howTo.3": "اگر گیر کردید از دکمه «Hint» استفاده کنید (هزینه‌اش امتیاز است)",
  "word.howTo.4": "برای تمام کردن پازل، 8 کلمه را کامل کنید",
  "hangman.howTo.1": "کلمه پنهان را یک حرف‌حرف حدس بزنید",
