  "kids.explorer.eco.ride.explain": "پیاده‌روی یا دوچرخه‌سواری برای سفرهای کوتاه هیچ آلودگی‌ای ایجاد نمی‌کند.",
  "kids.explorer.eco.ride.explainWrong": "ماشین‌ها سوخت مصرف می‌کنند و آلودگی تولید می‌کنند—برای سفرهای کوتاه، پیاده رفتن یا دوچرخه‌سواری پاک‌تر است.",
  "kids.explorer.eco.tree.prompt": "مدرسه‌تان در حال برنامه‌ریزی برای یک باغ است. چه چیزهایی باید داشته باشد؟",
